SELECT ?person ?en ?sv ?start ?end ?rank ?replaces ?replacedBy ?house ?houseEn ?houseSv WHERE {
  ?person p:P39 ?st .
  ?st ps:P39 wd:Q18341329 ; wikibase:rank ?rank .
  FILTER(?rank != wikibase:DeprecatedRank)
  OPTIONAL { ?st pq:P580 ?start }
  OPTIONAL { ?st pq:P582 ?end }
  OPTIONAL { ?st pq:P1365 ?replaces }
  OPTIONAL { ?st pq:P1366 ?replacedBy }
  OPTIONAL { ?person wdt:P53 ?house .
    OPTIONAL { ?house rdfs:label ?houseEn FILTER(LANG(?houseEn) = "en") }
    OPTIONAL { ?house rdfs:label ?houseSv FILTER(LANG(?houseSv) = "sv") } }
  OPTIONAL { ?person rdfs:label ?en FILTER(LANG(?en) = "en") }
  OPTIONAL { ?person rdfs:label ?sv FILTER(LANG(?sv) = "sv") }
}
ORDER BY ?start

SELECT ?person ?start ?end ?endCause ?endCauseEn ?father ?born ?houseProp ?houseVal WHERE {
  VALUES ?person { wd:Q153940 wd:Q157776 wd:Q154460 wd:Q157789 wd:Q154998 wd:Q154041 wd:Q153586 wd:Q157812
                   wd:Q157793 wd:Q161059 wd:Q154993 wd:Q156187 wd:Q156572 wd:Q155002 wd:Q157781 wd:Q94941
                   wd:Q151305 wd:Q152756 wd:Q156617 wd:Q151312 wd:Q102139 wd:Q1004037 }
  ?person p:P39 ?st .
  ?st ps:P39 wd:Q18341329 .
  OPTIONAL { ?st pq:P580 ?start }
  OPTIONAL { ?st pq:P582 ?end }
  OPTIONAL { ?st pq:P1534 ?endCause . OPTIONAL { ?endCause rdfs:label ?endCauseEn FILTER(LANG(?endCauseEn) = "en") } }
  OPTIONAL { ?person wdt:P22 ?father }
  OPTIONAL { ?person wdt:P569 ?born }
}
ORDER BY ?start

SELECT ?person ?mother ?motherEn WHERE {
  VALUES ?person { wd:Q1004037 }
  ?person wdt:P25 ?mother .
  OPTIONAL { ?mother rdfs:label ?motherEn FILTER(LANG(?motherEn) = "en") }
}

SELECT ?house ?p ?v ?vEn WHERE {
  VALUES ?house { wd:Q155594 wd:Q155616 wd:Q111201485 }
  VALUES ?p { wdt:P31 wdt:P279 wdt:P361 wdt:P127 wdt:P749 wdt:P112 wdt:P571 wdt:P17 }
  ?house ?p ?v .
  OPTIONAL { ?v rdfs:label ?vEn FILTER(LANG(?vEn) = "en") }
}

SELECT ?person ?pos ?posEn ?start ?end ?died WHERE {
  VALUES ?person { wd:Q153940 wd:Q157776 wd:Q154460 wd:Q156572 wd:Q155002 wd:Q157781 wd:Q102139 wd:Q1004037 wd:Q153586 }
  ?person p:P39 ?st .
  ?st ps:P39 ?pos .
  OPTIONAL { ?pos rdfs:label ?posEn FILTER(LANG(?posEn) = "en") }
  OPTIONAL { ?st pq:P580 ?start }
  OPTIONAL { ?st pq:P582 ?end }
  OPTIONAL { ?person wdt:P570 ?died }
}
ORDER BY ?person ?start

SELECT ?event ?eventEn ?pit ?start WHERE {
  wd:Q153586 p:P793 ?st .
  ?st ps:P793 ?event .
  OPTIONAL { ?event rdfs:label ?eventEn FILTER(LANG(?eventEn) = "en") }
  OPTIONAL { ?st pq:P585 ?pit }
  OPTIONAL { ?st pq:P580 ?start }
}
